customize.css:
/* A clean storefront look, written for this blog's own markup from measured values (pill buttons, 600-weight tight headings, white cards on a warm off-white page). */
:root{--wm-card:#fff;--wm-line:#ecebe7;--wm-chip:#f1f0ec;--wm-hover:#f1f0ec;--wm-btn:var(--link);--wm-shadow:0 8px 24px rgba(33,37,41,.08)}
@media (prefers-color-scheme:dark){:root{--bg:#14161a;--fg:#e8eaed;--muted:#9aa0a8;--link:#3ddc97;--wm-card:#1b1e23;--wm-line:#2a2e35;--wm-chip:#262a31;--wm-hover:#262a31;--wm-btn:#1f9d68;--wm-shadow:0 8px 24px rgba(0,0,0,.35)}}
body{line-height:1.6}
.wrap{padding-top:0}
.wrap:has(ul.posts){max-width:56rem}
header.site{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:.75rem;background:var(--wm-card);box-shadow:0 0 0 100vmax var(--wm-card);clip-path:inset(0 -100vmax);border:0;padding:1.1rem 0;margin:0 0 3rem;font-size:.95rem}
header.site a.brand{color:var(--fg);font-size:1.4rem;font-weight:700;letter-spacing:-.5px}
header.site a.brand::before{content:none}
header.site nav{display:flex;align-items:center;flex-wrap:wrap;gap:.15rem}
header.site nav a{margin:0;padding:.5rem .85rem;border-radius:9999px;color:var(--fg);font-size:.92rem;font-weight:500;letter-spacing:.2px;text-decoration:none}
header.site nav a::before{content:none}
header.site nav a:hover{background:var(--wm-hover);color:var(--fg)}
header.site nav a:last-child{background:var(--wm-btn);color:#fff;padding:.55rem 1.3rem;margin-left:.5rem}
header.site nav a:last-child:hover{filter:brightness(1.08);color:#fff}
h1,h2,h3{font-weight:600;letter-spacing:-.5px;line-height:1.12}
h1::before,h2::before,h3::before,ul.posts h2::before{content:none}
h1{font-size:clamp(2rem,5vw,3.2rem);margin:.1em 0 .25em}
h2{font-size:1.6rem}
h3{font-size:1.2rem}
body>.wrap>h1+.meta{font-size:1.15rem;color:var(--muted);margin:0 0 2.5rem}
a{text-underline-offset:.2em}
.meta{color:var(--muted);font-size:.85rem}
.meta .tag{display:inline-block;margin:0 0 0 .4rem;padding:.1rem .65rem;background:var(--wm-chip);border-radius:9999px;color:var(--fg);font-size:.78rem;font-weight:500;letter-spacing:.2px;text-decoration:none}
.meta .tag:hover{background:var(--wm-btn);color:#fff}
ul.posts{display:grid;grid-template-columns:repeat(auto-fill,minmax(19rem,1fr));gap:1.1rem;margin:0}
ul.posts li{display:flex;flex-direction:column;margin:0;padding:1.4rem 1.5rem;background:var(--wm-card);border:1px solid var(--wm-line);border-radius:16px;transition:box-shadow .15s,transform .15s}
ul.posts li:hover{box-shadow:var(--wm-shadow);transform:translateY(-2px)}
ul.posts .meta{order:-1;margin:0 0 .6rem}
ul.posts h2{font-size:1.2rem;line-height:1.25;letter-spacing:-.2px;margin:0 0 .45rem}
ul.posts h2 a{color:var(--fg);text-decoration:none}
ul.posts h2 a:hover{color:var(--link)}
ul.posts p{margin:0;color:var(--muted);font-size:.92rem;line-height:1.5}
article h1{font-size:clamp(2rem,5vw,2.8rem);margin-bottom:.35em}
img{border:0;border-radius:12px}
.cover img{border-radius:16px}
blockquote{border-left:4px solid var(--link);background:var(--wm-card);border-radius:0 12px 12px 0;padding:.8em 1.1em;color:var(--fg)}
pre{background:var(--wm-card);border:1px solid var(--wm-line);border-radius:12px}
code{background:var(--wm-chip);border-radius:6px}
pre code{background:none}
th{background:var(--wm-chip)}
th,td{border-color:var(--wm-line)}
hr{border-top:1px solid var(--wm-line)}
.post-nav,.navigation.pagination .nav-links{display:flex;justify-content:space-between;gap:.75rem;margin-top:2.5rem}
.post-nav a,.navigation.pagination a{display:inline-block;max-width:48%;padding:.65rem 1.3rem;border:1px solid var(--wm-line);border-radius:9999px;background:var(--wm-card);color:var(--fg);font-weight:500;text-decoration:none}
.post-nav a:hover,.navigation.pagination a:hover{background:var(--wm-btn);border-color:var(--wm-btn);color:#fff}
form[role=search] input,form.subscribe input{padding:.6rem 1.1rem;border:1px solid var(--wm-line);border-radius:9999px;background:var(--wm-card);color:var(--fg)}
form[role=search] button,form.subscribe button{padding:.6rem 1.4rem;border:0;border-radius:9999px;background:var(--wm-btn);color:#fff;font-weight:500;cursor:pointer}
footer.site{border-top:1px solid var(--wm-line);margin-top:4rem;color:var(--muted)}
::selection{background:var(--link);color:#fff}
@media (max-width:600px){header.site{padding:.9rem 0}header.site nav a:last-child{margin-left:0}ul.posts{grid-template-columns:1fr}}
@media (prefers-reduced-motion:reduce){ul.posts li{transition:none}ul.posts li:hover{transform:none}}
